values
  ('83bff9ae-aba0-4331-9be8-baf34ad2f84f', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', null, 'topic'::public.curated_course_node_type, 'Continuous- and discrete-time signals', 'This opening section gives students the language for describing signals before any filtering or analysis begins. The goal is to see physiological measurements as structured data: waveforms with units, timing, amplitude, morphology, and sampling choices.', 0),
  ('de4e4a43-f7ff-411c-86ac-b1c77ba65711', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '83bff9ae-aba0-4331-9be8-baf34ad2f84f', 'subtopic'::public.curated_course_node_type, 'Signal representations', 'Students learn to distinguish continuous waveforms from sampled sequences and to describe each with appropriate notation.', 0),
  ('1608dcf8-1e48-486b-8fc1-7e28325427b6', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'de4e4a43-f7ff-411c-86ac-b1c77ba65711', 'concept'::public.curated_course_node_type, 'Independent variable, amplitude, units, duration, and sampling index', null, 0),
  ('65e243ab-805d-4067-b3dc-efb7b5140984', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'de4e4a43-f7ff-411c-86ac-b1c77ba65711', 'concept'::public.curated_course_node_type, 'Analog waveforms versus digital records', null, 1),
  ('0fd4b74b-f277-4a8c-923a-3ac1e47bc08b', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'de4e4a43-f7ff-411c-86ac-b1c77ba65711', 'concept'::public.curated_course_node_type, 'Deterministic, random, periodic, aperiodic, energy, and power signals', null, 2),
  ('de226a71-267a-4625-9c2a-2c623ae2778e', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '83bff9ae-aba0-4331-9be8-baf34ad2f84f', 'subtopic'::public.curated_course_node_type, 'Biomedical waveform examples', 'The abstract notation is connected to real signals students will analyze later.', 1),
  ('c8ca558f-e791-46e3-b580-c91da3aaf1da', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'de226a71-267a-4625-9c2a-2c623ae2778e', 'concept'::public.curated_course_node_type, 'ECG Voltage Traces and Cardiac Cycles', null, 0),
  ('a9730f8e-76aa-42ab-a848-d7ab300c6ee3', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'de226a71-267a-4625-9c2a-2c623ae2778e', 'concept'::public.curated_course_node_type, 'EEG Rhythms and Neural Oscillations', null, 1),
  ('ae3b7429-4b70-430d-b500-9a28ee23f008', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'de226a71-267a-4625-9c2a-2c623ae2778e', 'concept'::public.curated_course_node_type, 'EMG Bursts, PPG Pulses, Pressure Traces, and Respiratory Signals', null, 2),
  ('a151ef3c-89bb-41b8-a133-6ec1f207494c', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '83bff9ae-aba0-4331-9be8-baf34ad2f84f', 'subtopic'::public.curated_course_node_type, 'Basic operations on signals', 'Operations help students model alignment, scaling, normalization, and comparison of recordings.', 2),
  ('285994c6-ac8a-4fc7-a0b1-038dc6775d1e', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'a151ef3c-89bb-41b8-a133-6ec1f207494c', 'concept'::public.curated_course_node_type, 'Time shifting, scaling, reversal, and windowing', null, 0),
  ('2835eba9-0724-43c4-acce-e8437508cd82', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'a151ef3c-89bb-41b8-a133-6ec1f207494c', 'concept'::public.curated_course_node_type, 'Amplitude scaling, baseline removal, and normalization', null, 1),
  ('da3e8457-7bab-4dfc-856d-cc12415e87d2', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'a151ef3c-89bb-41b8-a133-6ec1f207494c', 'concept'::public.curated_course_node_type, 'Signal arithmetic and segmentation', null, 2),
  ('db40de2a-29a2-43a6-a4ec-ae161c958f50', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '83bff9ae-aba0-4331-9be8-baf34ad2f84f', 'subtopic'::public.curated_course_node_type, 'Measurement context', 'Students learn that signals are shaped by physiology, sensors, and data-acquisition choices.', 3),
