  ('1528ef35-56c6-4770-b346-d82598149295', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'db40de2a-29a2-43a6-a4ec-ae161c958f50', 'concept'::public.curated_course_node_type, 'Units, calibration, and dynamic range', null, 1),
  ('dcca3c1c-3113-446d-907b-55924ea1aadd', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'db40de2a-29a2-43a6-a4ec-ae161c958f50', 'concept'::public.curated_course_node_type, 'Artifacts from motion, electrode contact, mains interference, and physiology outside the target system', null, 2),
  ('8b116c09-494a-46c8-a7a5-e256cc34ea22', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', null, 'topic'::public.curated_course_node_type, 'Linear time-invariant systems', 'LTI systems provide the central model for many filters, sensors, and simplified physiological subsystems. The point is not that every biological process is linear, but that linear models are powerful approximations when used carefully.', 1),
  ('c0cefac6-80a0-491a-a6d6-280fbcc9a942', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '8b116c09-494a-46c8-a7a5-e256cc34ea22', 'subtopic'::public.curated_course_node_type, 'Linearity and superposition', 'Students learn when outputs can be decomposed into responses to simpler inputs.', 0),
  ('37d22a0c-efe1-4bcb-bb61-5a87aa4e57dd', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'c0cefac6-80a0-491a-a6d6-280fbcc9a942', 'concept'::public.curated_course_node_type, 'Additivity and homogeneity', null, 0),
  ('ad3f0bd4-e4b7-400e-aa9b-b9cd3b7f051d', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'c0cefac6-80a0-491a-a6d6-280fbcc9a942', 'concept'::public.curated_course_node_type, 'Where biomedical systems are locally linear', null, 1),
  ('83aa3495-4e32-4cea-8cdc-9a7f0da941fb', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'c0cefac6-80a0-491a-a6d6-280fbcc9a942', 'concept'::public.curated_course_node_type, 'Limits of linear approximations in saturation, thresholds, and nonlinear physiology', null, 2),
  ('d04136d4-fd8a-4d1e-9808-839b0a31beae', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '8b116c09-494a-46c8-a7a5-e256cc34ea22', 'subtopic'::public.curated_course_node_type, 'Time invariance', 'This concept clarifies whether a system behaves the same way at different times.', 1),
  ('2da36730-5416-40ae-9517-d9381662511f', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'd04136d4-fd8a-4d1e-9808-839b0a31beae', 'concept'::public.curated_course_node_type, 'Shift-invariance tests', null, 0),
  ('bf616ca3-a10d-49b2-a94f-26a9abdaa688', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'd04136d4-fd8a-4d1e-9808-839b0a31beae', 'concept'::public.curated_course_node_type, 'Stationary versus changing systems', null, 1),
  ('704a5567-066a-488b-9eb3-8d6ef4e9df34', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'd04136d4-fd8a-4d1e-9808-839b0a31beae', 'concept'::public.curated_course_node_type, 'Examples from filters, amplifiers, and physiological regulation', null, 2),
  ('926454c6-9dcc-4252-ad3f-7b1b220f95a4', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '8b116c09-494a-46c8-a7a5-e256cc34ea22', 'subtopic'::public.curated_course_node_type, 'System properties', 'Students learn the vocabulary for judging system behavior before solving equations.', 2),
  ('b236ce5b-7254-4099-a45b-c82322734274', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '926454c6-9dcc-4252-ad3f-7b1b220f95a4', 'concept'::public.curated_course_node_type, 'Causality, memory, stability, and invertibility', null, 0),
  ('d73b37da-712e-4919-99a0-3116fd164944', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '926454c6-9dcc-4252-ad3f-7b1b220f95a4', 'concept'::public.curated_course_node_type, 'Static versus dynamic systems', null, 1),
  ('2687017f-a8b9-4262-9606-6e5fc27c54d7', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '926454c6-9dcc-4252-ad3f-7b1b220f95a4', 'concept'::public.curated_course_node_type, 'Initial conditions and system state', null, 2),
  ('99b737a4-7a7b-409b-ab88-e05567a17aea', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '8b116c09-494a-46c8-a7a5-e256cc34ea22', 'subtopic'::public.curated_course_node_type, 'Biomedical system models', 'The course connects LTI thinking to real measurement and physiology.', 3),
  ('f04fdfea-9f69-44ad-b7b5-bff5a7de6344', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '99b737a4-7a7b-409b-ab88-e05567a17aea', 'concept'::public.curated_course_node_type, 'Sensor and amplifier chains', null, 0),
  ('b3f6d495-ac69-4319-aea6-cd2b941a56ec', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '99b737a4-7a7b-409b-ab88-e05567a17aea', 'concept'::public.curated_course_node_type, 'Respiratory, cardiovascular, and neural response models', null, 1),
  ('7a57976f-1b22-420f-a2de-59794e3cd572', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '99b737a4-7a7b-409b-ab88-e05567a17aea', 'concept'::public.curated_course_node_type, 'Filter blocks in bedside monitors and wearable devices', null, 2),
  ('5753039b-2ffe-41c2-a0b9-98af7062b1e8', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', null, 'topic'::public.curated_course_node_type, 'Convolution and impulse response', 'Convolution explains how an input waveform is transformed by a system with memory. For biomedical engineering, it is the bridge between physical measurement chains, filtering, and interpretation of delayed or smeared signals.', 2),
  ('b6234089-918f-49b6-a938-5d55d35488ff', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '5753039b-2ffe-41c2-a0b9-98af7062b1e8', 'subtopic'::public.curated_course_node_type, 'Impulse response meaning', 'Students learn that the impulse response is a complete description of an LTI system.', 0),
  ('9b1a8667-2e42-4501-a19d-5e1cdfa09f56', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'b6234089-918f-49b6-a938-5d55d35488ff', 'concept'::public.curated_course_node_type, 'Unit impulse and unit sample', null, 0),
  ('331ad4f4-d46e-4701-aff6-2079d8840790', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'b6234089-918f-49b6-a938-5d55d35488ff', 'concept'::public.curated_course_node_type, 'Impulse-response measurement and interpretation', null, 1),
  ('96758e07-8128-4595-8da1-e8db005be882', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'b6234089-918f-49b6-a938-5d55d35488ff', 'concept'::public.curated_course_node_type, 'Biomedical examples such as sensor response time and hemodynamic response', null, 2),
  ('5146d8ec-5089-4d9e-8758-0ef057457806', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '5753039b-2ffe-41c2-a0b9-98af7062b1e8', 'subtopic'::public.curated_course_node_type, 'Convolution mechanics', 'Students practice the operation visually, analytically, and computationally.', 1),
  ('c0d7436c-1f52-455c-9207-16a1a1affaeb', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '5146d8ec-5089-4d9e-8758-0ef057457806', 'concept'::public.curated_course_node_type, 'Continuous convolution integral', null, 0),
