  ('82449174-1752-4867-9cea-d9c9ddc2a4a3', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '5146d8ec-5089-4d9e-8758-0ef057457806', 'concept'::public.curated_course_node_type, 'Graphical convolution and numerical implementation', null, 2),
  ('dcdd71a9-807d-485e-b074-33aac8398c3a', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '5753039b-2ffe-41c2-a0b9-98af7062b1e8', 'subtopic'::public.curated_course_node_type, 'System memory and smoothing', 'Convolution reveals why filters smooth, delay, or spread signal features.', 2),
  ('d90041c6-127f-4a83-82e7-6979c7fd0a60', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'dcdd71a9-807d-485e-b074-33aac8398c3a', 'concept'::public.curated_course_node_type, 'Moving-average filters', null, 0),
  ('dc07fb33-0bf4-4e67-80db-fa2ddb400940', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'dcdd71a9-807d-485e-b074-33aac8398c3a', 'concept'::public.curated_course_node_type, 'Exponential smoothing', null, 1),
  ('4d985e2b-d650-42f4-8537-812e7e0a7cc6', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'dcdd71a9-807d-485e-b074-33aac8398c3a', 'concept'::public.curated_course_node_type, 'Delay, ringing, and transient response', null, 2),
