  ('10ec169e-fb15-4c6a-a44c-1ae62c129169', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'b4ce4067-af4d-42ce-a216-f38d111bb192', 'concept'::public.curated_course_node_type, 'ECG Smoothing and QRS Morphology Effects', null, 0),
  ('b9f95a92-279d-46c6-8fc5-deac9fed1395', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'b4ce4067-af4d-42ce-a216-f38d111bb192', 'concept'::public.curated_course_node_type, 'Artifact spreading through filters', null, 1),
  ('7f1b69c5-8658-40d1-91ed-0286b81273fd', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'b4ce4067-af4d-42ce-a216-f38d111bb192', 'concept'::public.curated_course_node_type, 'Impulse-like events in neural or muscular recordings', null, 2),
  ('e9445e98-498a-4e58-b127-d01e70c044fd', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', null, 'topic'::public.curated_course_node_type, 'Fourier series and Fourier transforms', 'This section teaches students to analyze signals by frequency content. The point is to recognize rhythms, bandwidth, noise sources, and periodic structure that may be hidden in the time-domain trace.', 3),
  ('7bee30a3-b668-4d00-998d-84b8ce9a3022', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', 'e9445e98-498a-4e58-b127-d01e70c044fd', 'subtopic'::public.curated_course_node_type, 'Frequency-domain intuition', 'Students learn what a spectrum says about a signal.', 0),
  ('e0933581-15c0-4785-8d04-e81ad536a7d8', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '7bee30a3-b668-4d00-998d-84b8ce9a3022', 'concept'::public.curated_course_node_type, 'Sinusoids as building blocks', null, 0),
  ('4b16874a-ae04-4b9b-8dc4-62ca031e6c4f', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '7bee30a3-b668-4d00-998d-84b8ce9a3022', 'concept'::public.curated_course_node_type, 'Magnitude, phase, harmonics, and bandwidth', null, 1),
  ('d13c7f97-2b7d-4846-8095-299cd20cc56c', 'c5f1a750-7c7a-4b97-8114-134cae78a27f', '7bee30a3-b668-4d00-998d-84b8ce9a3022', 'concept'::public.curated_course_node_type, 'Periodicity, rhythm, and spectral peaks', null, 2),
